import logging
import datetime


class AccessGatewayFilter:

    # Symbolic constants to replace magic numbers
    MAX_USER_LEVEL = 2
    JWT_EXPIRY_DAYS = 3

    def __init__(self):
        pass

    def filter(self, request):
        request_uri = request['path']
        method = request['method']  # Unused variable - Remove Dead Code

        if self.is_allowed_path(request_uri):
            return True

        try:
            user = self.get_current_user(request)
            if self.is_user_level_valid(user):
                self.set_current_user_info_and_log(user)
                return True
            return False
        except Exception:
            return False

    def is_allowed_path(self, request_uri):
        allowed_prefixes = ["/api", "/login"]
        return any(request_uri.startswith(prefix) for prefix in allowed_prefixes)

    def get_current_user(self, request):
        token = request['headers']['Authorization']
        user = token['user']

        if self.is_jwt_expired(token, user):
            return None

        return user

    def is_jwt_expired(self, token, user):
        if not token['jwt'].startswith(user['name']):
            return False

        jwt_part = token['jwt'][len(user['name']):]
        # The original logic split by user name and took [1], which might be fragile.
        # Assuming the date follows the name directly.
        jwt_str_date = jwt_part
        jwt_date = datetime.datetime.strptime(jwt_str_date, "%Y-%m-%d")
        return (datetime.datetime.today() - jwt_date) >= datetime.timedelta(days=self.JWT_EXPIRY_DAYS)

    def is_user_level_valid(self, user):
        return user['level'] > self.MAX_USER_LEVEL

    def set_current_user_info_and_log(self, user):
        host = user['address']
        name = user['name']
        current_time = datetime.datetime.now()
        log_message = f"{name}{host}{current_time}"
        logging.log(msg=log_message, level=logging.DEBUG)
